"""Tests for cachetools.keys."""

import pickle

import pytest

from cachetools.keys import (
    _HashedTuple,
    _kwmark,
    hashkey,
    methodkey,
    typedkey,
    typedmethodkey,
)


class TestHashkey:
    def test_no_args(self):
        key = hashkey()
        assert key == ()
        assert isinstance(key, _HashedTuple)

    def test_positional_args(self):
        key = hashkey(1, 2, 3)
        assert key == (1, 2, 3)
        assert isinstance(key, _HashedTuple)

    def test_single_arg(self):
        assert hashkey("x") == ("x",)

    def test_with_kwargs(self):
        key = hashkey(1, 2, a=3, b=4)
        # args + _kwmark + sorted(kwargs.items())
        assert key == (1, 2) + _kwmark + (("a", 3), ("b", 4))

    def test_kwargs_sorted(self):
        k1 = hashkey(b=2, a=1)
        k2 = hashkey(a=1, b=2)
        assert k1 == k2

    def test_kwargs_only(self):
        key = hashkey(x=1)
        assert key == _kwmark + (("x", 1),)

    def test_positional_only_no_kwmark(self):
        key = hashkey(1, 2)
        assert _kwmark not in key

    def test_ordering_of_args_and_kwargs_matters(self):
        assert hashkey(1, a=2) != hashkey(1, ("a", 2))

    def test_hashable(self):
        key = hashkey(1, 2, a=3)
        assert hash(key) == hash((1, 2) + _kwmark + (("a", 3),))

    def test_unhashable_raises(self):
        key = hashkey([1, 2])
        with pytest.raises(TypeError):
            hash(key)

    def test_distinguishes_types(self):
        # untyped key ignores types
        assert hashkey(1) == hashkey(1)


class TestMethodkey:
    def test_self_dropped(self):
        class C:
            pass

        obj = C()
        assert methodkey(obj) == ()

    def test_self_and_args(self):
        assert methodkey("self", 1, 2) == (1, 2)

    def test_self_args_kwargs(self):
        key = methodkey("self", 1, a=2)
        assert key == (1,) + _kwmark + (("a", 2),)

    def test_matches_hashkey(self):
        assert methodkey("self", 1, a=2) == hashkey(1, a=2)

    def test_returns_hashed_tuple(self):
        assert isinstance(methodkey("self", 1), _HashedTuple)


class TestTypedkey:
    def test_no_args(self):
        assert typedkey() == ()

    def test_args_only(self):
        key = typedkey(1, "a")
        # args + types
        assert key == (1, "a", int, str)

    def test_distinguishes_types(self):
        assert typedkey(1) != typedkey(1.0)
        assert typedkey(1) == (1, int)
        assert typedkey(1.0) == (1.0, float)

    def test_with_kwargs(self):
        key = typedkey(1, a=2)
        expected = (
            (1,)
            + _kwmark
            + (("a", 2),)
            + (int,)  # type of kwargs value in sorted order
            + (int,)  # type of positional arg
        )
        assert key == expected

    def test_kwargs_sorted(self):
        assert typedkey(a=1, b=2) == typedkey(b=2, a=1)

    def test_kwargs_only(self):
        key = typedkey(x=1)
        assert key == _kwmark + (("x", 1),) + (int,)

    def test_kwargs_type_sensitive(self):
        assert typedkey(x=1) != typedkey(x=1.0)

    def test_returns_hashed_tuple(self):
        assert isinstance(typedkey(1, a=2), _HashedTuple)

    def test_ordering(self):
        # positional args and kwargs produce different keys
        assert typedkey(1, a=2) != typedkey(1, ("a", 2))

    def test_unhashable_raises(self):
        key = typedkey([1])
        with pytest.raises(TypeError):
            hash(key)


class TestTypedmethodkey:
    def test_self_dropped(self):
        assert typedmethodkey("self") == ()

    def test_self_and_args(self):
        assert typedmethodkey("self", 1, "a") == (1, "a", int, str)

    def test_self_args_kwargs(self):
        assert typedmethodkey("self", 1, a=2) == typedkey(1, a=2)

    def test_matches_typedkey(self):
        assert typedmethodkey("self", 1, a=2) == typedkey(1, a=2)

    def test_returns_hashed_tuple(self):
        assert isinstance(typedmethodkey("self", 1), _HashedTuple)


class TestHashedTuple:
    def test_hash_cached(self):
        calls = []

        class Element:
            def __init__(self, v):
                self.v = v

            def __hash__(self):
                calls.append(self.v)
                return hash(self.v)

            def __eq__(self, other):
                return isinstance(other, Element) and self.v == other.v

        elem = Element(5)
        t = _HashedTuple((elem,))
        h1 = hash(t)
        h2 = hash(t)
        h3 = hash(t)
        assert h1 == h2 == h3
        # hash called only once despite multiple hash() invocations
        assert calls == [5]

    def test_equality(self):
        assert _HashedTuple((1, 2)) == (1, 2)
        assert (1, 2) == _HashedTuple((1, 2))

    def test_add(self):
        t = _HashedTuple((1, 2))
        result = t + (3,)
        assert result == (1, 2, 3)
        assert isinstance(result, _HashedTuple)

    def test_radd(self):
        t = _HashedTuple((2, 3))
        result = (1,) + t
        assert result == (1, 2, 3)
        assert isinstance(result, _HashedTuple)

    def test_getstate(self):
        t = _HashedTuple((1, 2))
        assert t.__getstate__() == {}

    def test_pickle_roundtrip(self):
        t = _HashedTuple((1, 2, 3))
        restored = pickle.loads(pickle.dumps(t))
        assert restored == t
        assert hash(restored) == hash(t)

    def test_hash_matches_tuple_hash(self):
        t = _HashedTuple((1, "a", None))
        assert hash(t) == hash((1, "a", None))


class TestKwmark:
    def test_unique_identity(self):
        assert _kwmark == (_HashedTuple,)

    def test_pickle_preserves_identity(self):
        restored = pickle.loads(pickle.dumps(_kwmark))
        assert restored == _kwmark
        assert restored[0] is _HashedTuple
